module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
// Parameter declaration
parameter size = 4;
// Internal wires and registers
wire [7:0] mul_a_ext, mul_b_ext;
wire [7:0] partial_product [0:size-1];
reg [7:0] sum_reg [0:size-1];
reg [7:0] product_reg;
// Extend inputs
assign mul_a_ext = {{size{1'b0}}, mul_a};
assign mul_b_ext = {{size{1'b0}}, mul_b};
// Generate partial products
genvar i;
generate
    for(i = 0; i < size; i = i + 1) begin
        assign partial_product[i] = (mul_b[i]) ? (mul_a_ext << i) : 'd0;
    end
endgenerate
// Add partial products
integer j;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        for(j = 0; j < size; j = j + 1) begin
            sum_reg[j] <= 'd0;
        end
    end else begin
        for(j = 0; j < size; j = j + 1) begin
            sum_reg[j] <= partial_product[j] + sum_reg[j];
        end
    end
end
// Calculate final product
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        product_reg <= 'd0;
    end else begin
        product_reg <= sum_reg[0] + sum_reg[1] + sum_reg[2] + sum_reg[3];
    end
end
// Assign final product to output
assign mul_out = product_reg;
endmodule
